40	// FNV-1a 64 位内容哈希：同地图必同 hash、异地图（尺寸/分辨率/origin/栅格数据
41	// 任一变化）必异 hash，供调度侧版本门禁（expected_map_hash）比对与自身去重。
42	// 直接对 OccupancyGrid 消息计算（I1）：origin（平移/旋转）必须参与——仅平移
43	// 地图的尺寸与栅格 data 不变，漏掉 origin 会被去重误判为"同图"而跳过重导入；
44	// 消息级计算也让 check_timer_ 补跑时无需为去重重建 MapGrid。
45	std::string ComputeMapHash(const nav_msgs::msg::OccupancyGrid& msg) {
46	  uint64_t h = 14695981039346656037ULL;  // FNV-1a offset basis
47	  const auto mix = [&h](const void* bytes, std::size_t n) {
48	    const auto* p = static_cast<const uint8_t*>(bytes);
49	    for (std::size_t i = 0; i < n; ++i) {
50	      h ^= p[i];
51	      h *= 1099511628211ULL;  // FNV prime
52	    }
53	  };
54	  const auto mix_double = [&mix](double v) {
55	    uint64_t u = 0;
56	    static_assert(sizeof(u) == sizeof(v), "double must be 64-bit");
57	    std::memcpy(&u, &v, sizeof(v));
58	    mix(&u, sizeof(u));
59	  };
60	  mix(&msg.info.width, sizeof(msg.info.width));
61	  mix(&msg.info.height, sizeof(msg.info.height));
62	  mix(&msg.info.resolution, sizeof(msg.info.resolution));
63	  mix_double(msg.info.origin.position.x);
64	  mix_double(msg.info.origin.position.y);
65	  mix_double(amr_dispatcher_core::path_tracking::YawFromQuaternion(
66	      msg.info.origin.orientation.z, msg.info.origin.orientation.w));
67	  if (!msg.data.empty()) {
68	    mix(msg.data.data(), msg.data.size());
69	  }
70	  std::ostringstream out;
71	  out << "fnv1a64_" << std::hex << std::setfill('0') << std::setw(16) << h;
72	  return out.str();
73	}
