108	// double -> YAML 文本：max_digits10 保证往返解析不丢精度。
109	std::string FormatDouble(double v) {
110	  std::ostringstream out;
111	  out << std::setprecision(std::numeric_limits<double>::max_digits10) << v;
112	  return out.str();
113	}
