144	MapIngestNode::MapIngestNode(const rclcpp::NodeOptions& options)
145	    : rclcpp::Node("map_ingest_node", options) {
146	  declare_parameter<std::string>("map_topic", "/map");
147	  declare_parameter<std::string>("markers_file", "");
148	  declare_parameter<std::string>("output_stations_file", "config/generated/stations.yaml");
149	  declare_parameter<double>("robot_radius_m", 0.25);
150	  declare_parameter<double>("safety_margin_m", 0.05);
151	  declare_parameter<double>("min_branch_length_m", 0.5);
152	  declare_parameter<double>("max_snap_dist_m", 2.0);
153	  declare_parameter<bool>("publish_markers", true);
154	  declare_parameter<std::string>("marker_topic", "/dispatcher/topology_markers");
155	
156	  map_topic_ = get_parameter("map_topic").as_string();
157	  markers_file_ = get_parameter("markers_file").as_string();
158	  output_stations_file_ = get_parameter("output_stations_file").as_string();
159	  robot_radius_m_ = get_parameter("robot_radius_m").as_double();
160	  safety_margin_m_ = get_parameter("safety_margin_m").as_double();
161	  min_branch_length_m_ = get_parameter("min_branch_length_m").as_double();
162	  max_snap_dist_m_ = get_parameter("max_snap_dist_m").as_double();
163	  publish_markers_ = get_parameter("publish_markers").as_bool();
164	  marker_topic_ = get_parameter("marker_topic").as_string();
165	
166	  // transient_local + reliable：与 nav2_map_server / 静态地图发布者的
167	  // latched 语义对接——即使 map_ingest_node 启动晚于 map_server 也能收到地图。
168	  map_sub_ = create_subscription<OccupancyGrid>(
169	      map_topic_, rclcpp::QoS(rclcpp::KeepLast(1)).transient_local().reliable(),
170	      std::bind(&MapIngestNode::MapCallback, this, std::placeholders::_1));
171	
172	  // transient_local：RViz 晚启动也能立即看到完整拓扑。
173	  marker_pub_ = create_publisher<visualization_msgs::msg::MarkerArray>(
174	      marker_topic_, rclcpp::QoS(rclcpp::KeepLast(1)).transient_local());
175	
176	  // I2：/map 是 latched 单发消息——首次回调若 markers 未就绪则本次作废，此后
177	  // 由 1Hz 定时器基于缓存地图自动补跑（成功后 markers 被编辑同样经此再生成）。
178	  check_timer_ = create_wall_timer(std::chrono::seconds(1),
179	                                   std::bind(&MapIngestNode::CheckTimerCallback, this));
180	
181	  RCLCPP_INFO(get_logger(),
182	              "MapIngestNode started: map_topic=%s markers_file='%s' output='%s' "
183	              "(robot_radius=%.2fm margin=%.2fm min_branch=%.2fm max_snap=%.2fm)",
184	              map_topic_.c_str(), markers_file_.c_str(), output_stations_file_.c_str(),
185	              robot_radius_m_, safety_margin_m_, min_branch_length_m_, max_snap_dist_m_);
186	}
