188	std::vector<AnchorStation> MapIngestNode::LoadAnchors() {
189	  std::vector<AnchorStation> anchors;
190	  if (markers_file_.empty()) {
191	    return anchors;
192	  }
193	  std::error_code ec;
194	  if (!std::filesystem::exists(markers_file_, ec)) {
195	    // 节流：check_timer_ 会以 1Hz 重入本函数，避免等待窗口刷屏。
196	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
197	                        "markers_file '%s' does not exist yet; waiting",
198	                        markers_file_.c_str());
199	    return anchors;
200	  }
201	  try {
202	    const YAML::Node root = YAML::LoadFile(markers_file_);
203	    if (!root["anchors"] || !root["anchors"].IsSequence()) {
204	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
205	                          "markers_file '%s' has no 'anchors' list; waiting",
206	                          markers_file_.c_str());
207	      return anchors;
208	    }
209	    for (const auto& node : root["anchors"]) {
210	      AnchorStation anchor;
211	      anchor.id = node["id"].as<std::string>();
212	      anchor.type = node["type"].as<std::string>("normal");
213	      anchor.x = node["x"].as<double>();
214	      anchor.y = node["y"].as<double>();
215	      anchor.yaw = node["yaw"].as<double>(0.0);
216	      if (anchor.id.empty()) {
217	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
218	                            "markers_file '%s' contains an anchor with empty id; skipped",
219	                            markers_file_.c_str());
220	        continue;
221	      }
222	      anchors.push_back(std::move(anchor));
223	    }
224	  } catch (const std::exception& e) {
225	    RCLCPP_ERROR_THROTTLE(get_logger(), *get_clock(), 10000,
226	                         "Failed to parse markers_file '%s': %s",
227	                         markers_file_.c_str(), e.what());
228	    anchors.clear();
229	  }
230	  return anchors;
231	}
