233	std::string MapIngestNode::SerializeCatalog(const StationCatalog& catalog) {
234	  // 与 LoadStationCatalog 的逐行严格解析 schema 对齐（Task 1）：
235	  // version(map_hash/graph_version) -> stations -> road_nodes -> edges(polyline)。
236	  std::ostringstream out;
237	  out << "version:\n";
238	  out << "  map_hash: " << Quote(catalog.map_hash) << "\n";
239	  out << "  graph_version: " << Quote(catalog.graph_version) << "\n";
240	
241	  out << "stations:\n";
242	  for (const auto& station : catalog.stations) {
243	    out << "  - id: " << Quote(station.id) << "\n";
244	    out << "    x: " << FormatDouble(station.x) << "\n";
245	    out << "    y: " << FormatDouble(station.y) << "\n";
246	    out << "    yaw: " << FormatDouble(station.yaw) << "\n";
247	    out << "    type: " << Quote(station.type) << "\n";
248	  }
249	
250	  out << "road_nodes:\n";
251	  for (const auto& node : catalog.road_nodes) {
252	    out << "  - id: " << Quote(node.id) << "\n";
253	    out << "    x: " << FormatDouble(node.x) << "\n";
254	    out << "    y: " << FormatDouble(node.y) << "\n";
255	    out << "    yaw: " << FormatDouble(node.yaw) << "\n";
256	  }
257	
258	  out << "edges:\n";
259	  for (const auto& edge : catalog.edges) {
260	    out << "  - from: " << Quote(edge.from) << "\n";
261	    out << "    to: " << Quote(edge.to) << "\n";
262	    out << "    distance_m: " << FormatDouble(edge.distance_m) << "\n";
263	    out << "    bidirectional: " << (edge.bidirectional ? "true" : "false") << "\n";
264	    out << "    enabled: " << (edge.enabled ? "true" : "false") << "\n";
265	    out << "    polyline:\n";
266	    for (const auto& point : edge.polyline) {
267	      out << "      - [" << FormatDouble(point.first) << ", " << FormatDouble(point.second)
268	          << "]\n";
269	    }
270	  }
271	  return out.str();
272	}
