274	bool MapIngestNode::WriteCatalogAtomic(const StationCatalog& catalog) const {
275	  const std::filesystem::path final_path(output_stations_file_);
276	  const std::filesystem::path tmp_path(final_path.string() + ".tmp");
277	  std::error_code ec;
278	
279	  if (final_path.has_parent_path()) {
280	    std::filesystem::create_directories(final_path.parent_path(), ec);
281	    if (ec) {
282	      RCLCPP_ERROR(get_logger(), "Cannot create directory for %s: %s",
283	                   final_path.parent_path().string().c_str(), ec.message().c_str());
284	      return false;
285	    }
286	  }
287	
288	  {
289	    std::ofstream out(tmp_path, std::ios::trunc);
290	    if (!out) {
291	      RCLCPP_ERROR(get_logger(), "Cannot open temp file %s for writing", tmp_path.c_str());
292	      return false;
293	    }
294	    out << SerializeCatalog(catalog);
295	    out.flush();
296	    if (!out) {
297	      out.close();
298	      std::filesystem::remove(tmp_path, ec);
299	      RCLCPP_ERROR(get_logger(), "Failed writing temp file %s", tmp_path.c_str());
300	      return false;
301	    }
302	  }
303	
304	  // 回读校验：tmp 文件必须能被调度侧的严格解析器 LoadStationCatalog 接受，
305	  // 否则删除 tmp、保留旧文件——绝不让半截/坏目录进入热重载路径。
306	  if (!LoadStationCatalog(tmp_path)) {
307	    std::filesystem::remove(tmp_path, ec);
308	    RCLCPP_ERROR(get_logger(),
309	                 "Round-trip validation failed for %s; generated YAML is not parseable "
310	                 "by LoadStationCatalog (keeping existing catalog)",
311	                 tmp_path.c_str());
312	    return false;
313	  }
314	
315	  // 同目录内 rename(2) 为原子操作：调度端要么看到旧文件要么看到新文件。
316	  std::filesystem::rename(tmp_path, final_path, ec);
317	  if (ec) {
318	    std::filesystem::remove(tmp_path, ec);
319	    RCLCPP_ERROR(get_logger(), "Atomic rename %s -> %s failed: %s", tmp_path.c_str(),
320	                 final_path.c_str(), ec.message().c_str());
321	    return false;
322	  }
323	  return true;
324	}
