326	void MapIngestNode::MapCallback(const OccupancyGrid::SharedPtr msg) {
327	  if (msg->info.width == 0 || msg->info.height == 0) {
328	    RCLCPP_WARN(get_logger(), "Ignoring invalid map: width=%u height=%u", msg->info.width,
329	                msg->info.height);
330	    return;
331	  }
332	  const std::size_t expected_cells =
333	      static_cast<std::size_t>(msg->info.width) * msg->info.height;
334	  if (msg->data.size() != expected_cells) {
335	    RCLCPP_WARN(get_logger(), "Ignoring malformed map: data size %zu != %u x %u",
336	                msg->data.size(), msg->info.width, msg->info.height);
337	    return;
338	  }
339	
340	  // I2：/map 单发（transient_local）不会重来——缓存消息与内容 hash（I1 含
341	  // origin），本次立即处理；若 markers 未就绪，check_timer_ 之后基于缓存补跑。
342	  last_map_msg_ = msg;
343	  last_map_hash_ = ComputeMapHash(*msg);
344	  ProcessMap();
345	}
