455	void MapIngestNode::PublishTopologyMarkers(const StationCatalog& catalog) {
456	  visualization_msgs::msg::MarkerArray array;
457	  const auto stamp = now();
458	
459	  // 先 DELETEALL 清残影：重新导入（地图更新）时上一批 Marker 全部作废。
460	  visualization_msgs::msg::Marker clear;
461	  clear.header.frame_id = map_frame_id_;
462	  clear.header.stamp = stamp;
463	  clear.ns = "topology_reset";
464	  clear.id = 0;
465	  clear.action = visualization_msgs::msg::Marker::DELETEALL;
466	  array.markers.push_back(clear);
467	
468	  int id = 0;
469	  const auto base_marker = [&](const std::string& ns, int type) {
470	    visualization_msgs::msg::Marker marker;
471	    marker.header.frame_id = map_frame_id_;
472	    marker.header.stamp = stamp;
473	    marker.ns = ns;
474	    marker.id = id++;
475	    marker.type = type;
476	    marker.action = visualization_msgs::msg::Marker::ADD;
477	    marker.pose.orientation.w = 1.0;
478	    // 永久驻留（lifetime=0）+ transient_local 发布：晚加入的 RViz 也能看到。
479	    return marker;
480	  };
481	
482	  // 端点查找表：折线退化（<2 点）时回退用站点/节点坐标补两个端点。
483	  std::unordered_map<std::string, std::pair<double, double>> endpoint_xy;
484	  for (const auto& node : catalog.road_nodes) {
485	    endpoint_xy[node.id] = {node.x, node.y};
486	    auto marker = base_marker("road_nodes", visualization_msgs::msg::Marker::SPHERE);
487	    marker.pose.position.x = node.x;
488	    marker.pose.position.y = node.y;
489	    marker.pose.position.z = 0.05;
490	    marker.scale.x = 0.15;
491	    marker.scale.y = 0.15;
492	    marker.scale.z = 0.15;
493	    marker.color = Color(0.65f, 0.65f, 0.65f, 0.9f);
494	    array.markers.push_back(marker);
495	  }
496	
497	  for (const auto& station : catalog.stations) {
498	    endpoint_xy[station.id] = {station.x, station.y};
499	    auto marker = base_marker("stations", visualization_msgs::msg::Marker::CYLINDER);
500	    marker.pose.position.x = station.x;
501	    marker.pose.position.y = station.y;
502	    marker.pose.position.z = 0.05;
503	    marker.scale.x = 0.3;
504	    marker.scale.y = 0.3;
505	    marker.scale.z = 0.1;
506	    marker.color = StationColor(station.type);
507	    array.markers.push_back(marker);
508	
509	    auto label = base_marker("station_labels", visualization_msgs::msg::Marker::TEXT_VIEW_FACING);
510	    label.pose.position.x = station.x;
511	    label.pose.position.y = station.y;
512	    label.pose.position.z = 0.5;
513	    label.scale.z = 0.25;
514	    label.color = Color(1.0f, 1.0f, 1.0f, 0.95f);
515	    label.text = station.id;
516	    array.markers.push_back(label);
517	  }
518	
519	  // 边：LINE_STRIP 沿真实 polyline 走廊中心线（而非两点直线）。
520	  for (const auto& edge : catalog.edges) {
521	    auto marker = base_marker("edges", visualization_msgs::msg::Marker::LINE_STRIP);
522	    marker.scale.x = 0.06;  // 线宽（米）
523	    marker.color = Color(0.1f, 0.8f, 0.9f, 0.9f);
524	    if (edge.polyline.size() >= 2) {
525	      marker.points.reserve(edge.polyline.size());
526	      for (const auto& point : edge.polyline) {
527	        geometry_msgs::msg::Point p;
528	        p.x = point.first;
529	        p.y = point.second;
530	        p.z = 0.03;
531	        marker.points.push_back(p);
532	      }
533	    } else {
534	      // 折线缺失的退化边：以两端点连线兜底，保证拓扑关系仍可视化。
535	      const auto from = endpoint_xy.find(edge.from);
536	      const auto to = endpoint_xy.find(edge.to);
537	      if (from == endpoint_xy.end() || to == endpoint_xy.end()) {
538	        continue;
539	      }
540	      geometry_msgs::msg::Point a;
541	      a.x = from->second.first;
542	      a.y = from->second.second;
543	      a.z = 0.03;
544	      geometry_msgs::msg::Point b;
545	      b.x = to->second.first;
546	      b.y = to->second.second;
547	      b.z = 0.03;
548	      marker.points.push_back(a);
549	      marker.points.push_back(b);
550	    }
551	    array.markers.push_back(marker);
552	  }
553	
554	  marker_pub_->publish(array);
555	  RCLCPP_INFO(get_logger(), "Published topology markers: %zu stations, %zu road nodes, "
556	              "%zu edges on %s",
557	              catalog.stations.size(), catalog.road_nodes.size(), catalog.edges.size(),
558	              marker_topic_.c_str());
559	}
