class PurePursuitController {
 public:
  struct Config {
    double lookahead_distance = 0.8;   // 前置距离 (m)
    double target_speed = 0.35;        // 期望线速度 (m/s)
    double max_angular_speed = 1.2;    // 角速度限幅 (rad/s)
    double goal_tolerance = 0.10;      // 终点判定容差 (m)
